{
  "type": "function",
  "function": {
    "name": "schedule_freight_pickup",
    "description": "Schedules a freight pickup using the supplied UTC pickup time, declared currency, shipment weight, and depot coordinates. Use this tool when a freight pickup needs to be arranged; do not use it for quoting rates or tracking an existing shipment. Provide the shipment weight in kilograms and coordinates as latitude,longitude with no spaces. The carrier note may be null when there are no additional instructions; this tool does not validate carrier-specific service availability.",
    "strict": true,
    "parameters": {
      "type": "object",
      "properties": {
        "pickup_iso_utc": {
          "type": "string",
          "format": "date-time",
          "pattern": "Z$",
          "description": "ISO 8601 date-time in UTC, ending in Z (for example, 2026-04-15T14:30:00Z); do not use a numeric offset or local time."
        },
        "declared_currency": {
          "type": "string",
          "pattern": "^[A-Z]{3}$",
          "description": "Three-letter uppercase ISO 4217 currency code (for example, USD or EUR)."
        },
        "weight_kg": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "Shipment weight in kilograms; must be greater than zero."
        },
        "depot_coordinates": {
          "type": "string",
          "pattern": "^-?[0-9]+(?:\\.[0-9]+)?,-?[0-9]+(?:\\.[0-9]+)?$",
          "description": "Decimal latitude and longitude in the exact format lat,lon, with no spaces, including after the comma (for example, 37.7749,-122.4194). Latitude must be between -90 and 90, and longitude between -180 and 180."
        },
        "carrier_note": {
          "type": [
            "string",
            "null"
          ],
          "description": "Optional instructions for the carrier, or null if no note is needed."
        }
      },
      "required": [
        "pickup_iso_utc",
        "declared_currency",
        "weight_kg",
        "depot_coordinates",
        "carrier_note"
      ],
      "additionalProperties": false
    }
  }
}

{
  "type": "function",
  "function": {
    "name": "issue_prorated_credit",
    "description": "Calculates and submits a prorated net credit for a canceled subscription. Use this tool when a customer is eligible for a credit based on the unused portion of the current billing cycle; do NOT use it for refunds based on usage, discretionary goodwill credits, or credits unrelated to a cancellation. The credit is calculated in integer cents using the half-open billing interval [billing_start, billing_end): unused_days is the number of calendar days in [cancel_date, billing_end), and cycle_days is the number of calendar days in [billing_start, billing_end). gross_credit_cents is the plan price in cents multiplied by unused_days and divided by cycle_days, rounded to the nearest cent with exact half-cent ties rounded up; net_credit_cents is gross_credit_cents minus flat_fee_cents, floored at zero. Submit the calculated unused_days and net_credit_cents along with the source inputs; dates must be ISO 8601 calendar dates, billing_start < cancel_date < billing_end, plan_price_cents must be positive, and flat_fee_cents must be nonnegative. The server validates the calculation and may reject inconsistent arguments; this tool does not determine eligibility or return a tax-adjusted amount.",
    "strict": true,
    "parameters": {
      "type": "object",
      "properties": {
        "rationale": {
          "type": "string",
          "description": "Briefly state the arithmetic used to derive unused_days and net_credit_cents, including the day-count interval and rounding rule. Keep this concise; do not provide hidden chain-of-thought or step-by-step thinking."
        },
        "billing_start": {
          "type": "string",
          "format": "date",
          "description": "Inclusive first calendar day of the billing cycle, ISO 8601 YYYY-MM-DD."
        },
        "billing_end": {
          "type": "string",
          "format": "date",
          "description": "Exclusive end boundary of the billing cycle, ISO 8601 YYYY-MM-DD; must be later than billing_start."
        },
        "cancel_date": {
          "type": "string",
          "format": "date",
          "description": "Inclusive first unused calendar day, ISO 8601 YYYY-MM-DD; must be later than billing_start and earlier than billing_end."
        },
        "plan_price_cents": {
          "type": "integer",
          "minimum": 1,
          "description": "Full-cycle plan price as a positive integer number of cents, e.g. 12000 for $120.00."
        },
        "flat_fee_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Flat fee to subtract from the gross prorated credit, as a nonnegative integer number of cents; net credit is floored at zero."
        },
        "unused_days": {
          "type": "integer",
          "minimum": 1,
          "description": "Calculated number of calendar days in [cancel_date, billing_end), equal to billing_end minus cancel_date in calendar days."
        },
        "net_credit_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Calculated net credit in integer cents: max(0, round_half_up(plan_price_cents × unused_days ÷ cycle_days) − flat_fee_cents), where cycle_days is billing_end minus billing_start in calendar days. Round exact half-cent ties up."
        }
      },
      "required": [
        "rationale",
        "billing_start",
        "billing_end",
        "cancel_date",
        "plan_price_cents",
        "flat_fee_cents",
        "unused_days",
        "net_credit_cents"
      ],
      "additionalProperties": false
    }
  }
}

{
  "type": "function",
  "function": {
    "name": "issue_prorated_credit",
    "description": "Issue a prorated net credit. Before calling, calculate both derived values exactly from the supplied inputs. Treat dates as ISO 8601 calendar dates and the billing interval as [billing_start, billing_end). Let total_days = billing_end − billing_start in calendar days. Let unused_days = clamp(billing_end − cancel_date, 0, total_days) in calendar days; the cancellation date itself is unused. Calculate gross_credit_cents by rounding plan_price_cents × unused_days ÷ total_days to the nearest cent, with exact half-cent ties rounded up. Calculate net_credit_cents = max(0, gross_credit_cents − flat_fee_cents). Submit the derived integer values along with the inputs. Do not estimate or use floating-point rounding.",
    "strict": true,
    "parameters": {
      "type": "object",
      "properties": {
        "billing_start": {
          "type": "string",
          "description": "Billing-cycle start date, inclusive, in YYYY-MM-DD format."
        },
        "billing_end": {
          "type": "string",
          "description": "Billing-cycle end date, exclusive, in YYYY-MM-DD format; must be later than billing_start."
        },
        "cancel_date": {
          "type": "string",
          "description": "Cancellation effective date in YYYY-MM-DD format."
        },
        "plan_price_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Full-cycle plan price in integer cents."
        },
        "flat_fee_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Flat fee to subtract from the gross prorated credit, in integer cents."
        },
        "unused_days": {
          "type": "integer",
          "minimum": 0,
          "description": "Calculated unused calendar days: clamp(billing_end − cancel_date, 0, total_days), where total_days = billing_end − billing_start."
        },
        "net_credit_cents": {
          "type": "integer",
          "minimum": 0,
          "description": "Calculated net credit in cents: max(0, round-half-up(plan_price_cents × unused_days ÷ total_days) − flat_fee_cents)."
        }
      },
      "required": [
        "billing_start",
        "billing_end",
        "cancel_date",
        "plan_price_cents",
        "flat_fee_cents",
        "unused_days",
        "net_credit_cents"
      ],
      "additionalProperties": false
    }
  }
}

