        },
        "billing_start": {
          "type": "string",
          "format": "date",
          "description": "Billing cycle start date in ISO 8601 YYYY-MM-DD format; inclusive."
        },
        "billing_end": {
          "type": "string",
          "format": "date",
          "description": "Billing cycle end date in ISO 8601 YYYY-MM-DD format; exclusive. Must be later than billing_start."
        },
        "cancel_date": {
          "type": "string",
          "format": "date",
          "description": "Cancellation effective date in ISO 8601 YYYY-MM-DD format. Unused days are the calendar days in [cancel_date, billing_end); must be within [billing_start, billing_end]."
