          "minimum": 0,
          "description": "Flat fee to subtract from the gross prorated amount, as a nonnegative integer number of cents."
        },
        "unused_billing_days": {
          "type": "integer",
          "minimum": 0,
          "description": "Exact calendar-day count from cancel_date inclusive to billing_end exclusive: (billing_end - cancel_date).days. The full cycle day count is (billing_end - billing_start).days."
